/**
 * @param {number} k
 * @param {number[]} arrival
 * @param {number[]} load
 * @return {number[]}
 */
var busiestServers = function(k, arrival, load) {
    const busy = new MinPriorityQueue((el) => el[0]);

    const n = arrival.length;
    const mid = Math.min(k, n);
    const dp = Array(k).fill(0);
    const attributed = Array(k).fill(false);
    let free = k;

    for (let i = 0; i < mid; i++) {
        dp[i]++;
        busy.enqueue([arrival[i] + load[i], i]);
        attributed[i] = true;
        free--;
    }

    for (let i = mid; i < n; i++) {
        const time = arrival[i];

        while (!busy.isEmpty() && busy.front()[0] <= time) {
            const [_, el] = busy.dequeue();
            attributed[el] = false;
            free++;
        }

        if (free > 0) {
            let el;

            for (let j = 0; j < k; j++) {
                const pos = (i + j) % k;
                if (!attributed[pos]) {
                    el = pos;
                    break;
                }
            }

            dp[el]++;
            busy.enqueue([time + load[i], el]);
            attributed[el] = true;
            free--;
        }
    }

    const max = Math.max(...dp);
    const res = [];

    for (let i = 0; i < k; i++) {
        if (dp[i] === max) {
            res.push(i);
        }
    }

    return res;
};

/** By Leetcode */
var busiestServers = function(k, arrival, load) {
    const free = new PriorityQueue((a, b) => a - b, [...Array(k).keys()]);  // each free server, keyed by its next turn
    const busy = new PriorityQueue((a, b) => a[0] - b[0]);  // [time it frees up, server]

    const handled = new Array(k).fill(0);
    for (const [i, t] of arrival.entries()) {
        while (!busy.isEmpty() && busy.front()[0] <= t) {  // done by the arrival
            const [, x] = busy.dequeue();
            free.enqueue(i + (x - i % k + k) % k);  // its first turn from i on
        }
        if (free.isEmpty()) continue;  // none free: the request is dropped
        const x = free.dequeue() % k;
        busy.enqueue([t + load[i], x]);
        handled[x]++;
    }

    const most = handled.reduce((a, b) => Math.max(a, b));
    return [...handled.keys()].filter(x => handled[x] === most);
};
